<?php
declare(strict_types=1);
final class AdminExportController{private ExportRepository $repo;public function __construct(private PDO $db){$this->repo=new ExportRepository($db);}public function index():string{return view('admin/exports/index',['items'=>$this->repo->all(),'title'=>'Exportaciones','section'=>'exportaciones']);}public function generate():never{if(!verify_csrf())throw new RuntimeException('La sesión expiró.');$id=(new ExportService($this->db))->generate((string)($_POST['type']??'perfumes'),(string)($_POST['format']??'csv'));redirect('admin/exportaciones/'.$id);}public function show(mixed $id):string{$item=$this->repo->find((int)$id);if(!$item){http_response_code(404);return view('errors/404');}return view('admin/exports/show',['item'=>$item,'title'=>'Exportación','section'=>'exportaciones']);}public function download(mixed $id):never{$item=$this->repo->find((int)$id);if(!$item||!is_file($item['file_path'])||($item['expires_at']&&strtotime($item['expires_at'])<time())){http_response_code(404);exit;}header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.basename($item['filename']).'"');readfile($item['file_path']);exit;}}
